int sblkmap[64][8] = {0};

uint8_t stuckBitMaskOnesMap[64][8][64] = {0};
uint8_t stuckBitMaskZerosMap[64][8][64] = {0};

void resetFaultyCacheMaps() {
  for (int i = 0; i < 64; i++) {
    for (int j = 0; j < 8; j++) {
      sblkmap[i][j] = 0;
      for (int k = 0; k < 64; k++) {
        stuckBitMaskOnesMap[i][j][k] = 0;
        stuckBitMaskZerosMap[i][j][k] = UINT8_MAX; // 255
      }
    }
  }
}

